    @EventHandler( payloadType=CreateObligationEvent.class )
    public void handle( CreateObligationEvent event) {
	    LOGGER.info("handling CreateObligationEvent - " + event );
	    Obligation entity = new Obligation();
            entity.setObligationId( event.getObligationId() );
            entity.setReferenceNumber( event.getReferenceNumber() );
            entity.setDescriptionText( event.getDescriptionText() );
            entity.setObligationType( event.getObligationType() );
            entity.setReviewFrequency( event.getReviewFrequency() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllObligation( entity );
    }

