    /**
     * Method to retrieve the Obligation via an ObligationPrimaryKey.
     * @param 	id Long
     * @return 	Obligation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Obligation handle( FindObligationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getObligationId() );
    }
    
    /**
     * Method to retrieve a collection of all Obligations
     *
     * @param	query	FindAllObligationQuery 
     * @return 	List<Obligation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Obligation> handle( FindAllObligationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindObligation,
 * but only if the id matches
 *
 * @param		entity	Obligation
 */
	protected void emitFindObligation( Obligation entity ) {
		LOGGER.info("handling emitFindObligation" );
		
	    queryUpdateEmitter.emit(FindObligationQuery.class,
	                            query -> query.getFilter().getObligationId().equals(entity.getObligationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllObligation
	 * 
	 * @param		entity	Obligation
	 */
	protected void emitFindAllObligation( Obligation entity ) {
		LOGGER.info("handling emitFindAllObligation" );
		
	    queryUpdateEmitter.emit(FindAllObligationQuery.class,
	                            query -> true,
	                            entity);
	}

